func ServiceIntent(proof Profile, architecture string) (swarmruntime.ServiceIntent, error) {
	intent, profile := proof.intent, proof.profile
	region, known := catalog.LookupName(proof.identity.Cell)
	if proof.fingerprint == "" || !known || intent.Container == nil {
		return swarmruntime.ServiceIntent{}, ErrPending
	}
	envelope, err := trust.DecodeEnvelope(intent.Container.Claim)
	if err != nil {
		return swarmruntime.ServiceIntent{}, err
	}
	var claim release.ContainerClaim
	if protocol.DecodeStrict(envelope.Payload, &claim, trust.MaxPayloadBytes) != nil || claim.Validate() != nil ||
		claim.Cell != region.Cell || claim.Environment != intent.Environment || claim.Role != intent.Role || claim.Architecture != architecture {
		return swarmruntime.ServiceIntent{}, ErrPending
	}
	environment := make([]string, 0, len(profile.Env))
	for _, key := range slices.Sorted(maps.Keys(profile.Env)) {
		environment = append(environment, key+"="+profile.Env[key])
	}
	limits := &api.Resources{NanoCPUs: int64(profile.Resources.CPU) * 1_000_000_000, MemoryBytes: profile.Resources.MemoryBytes, Generic: []*api.GenericResource{genericresource.NewDiscrete(swarmruntime.DiskResource, profile.Resources.DiskBytes)}}
	expected := swarmruntime.ServiceIntent{ID: entityid.Derive("platform-service", intent.Role, intent.Environment, region.OCIRegion), OperationID: intent.OperationID, Generation: intent.Generation,
		Role: intent.Role, Region: region.OCIRegion, Environment: intent.Environment, Architecture: architecture, Replicas: uint64(intent.DesiredReplicas),
		Container: &api.ContainerSpec{Image: claim.Image, User: "65532:65532", Args: slices.Clone(profile.Args), Env: environment},
		Resources: &api.ResourceRequirements{Limits: limits, Reservations: limits.Copy()}}
	if intent.Role == "ts-auth" {
		expected.Ports = []*api.PortConfig{{Protocol: api.ProtocolTCP, TargetPort: 8080, PublishedPort: 8080, PublishMode: api.PublishModeHost}}
	}
	return expected, nil
}

cellspec-sign.text:
func Sign(spec Spec, delegationWire []byte, roots trust.Keyring, now time.Time, validFor time.Duration,
	signer ed25519.PrivateKey,
) ([]byte, error) {
	if spec.Generation == 0 {
		return nil, fmt.Errorf("%w: generation 0 is the signed controller config's spec", ErrInvalid)
	}
	if validFor <= 0 || validFor > MaxSpecLifetime {
		return nil, fmt.Errorf("cell spec validity must be positive and at most %s", MaxSpecLifetime)
	}
	payload, err := Encode(spec)
	if err != nil {
		return nil, err
	}
	issuedAt := now.Round(0).UTC().Truncate(time.Second)
	envelope, err := trust.Sign(payload, spec.Identity.Scope(), issuedAt, issuedAt.Add(validFor), signer)
	if err != nil {
		return nil, err
	}
	specWire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(Signed{Delegation: bytes.Clone(delegationWire), Spec: specWire})
	if err != nil {
		return nil, err
	}
	if _, err := VerifyCurrent(wire, roots, spec.Identity, now); err != nil {
		return nil, err
	}
	return wire, nil
}

cellspec-verify.text:
func VerifyCurrent(wire []byte, roots trust.Keyring, id Identity, now time.Time) (Verified, error) {
	return verify(wire, roots, id, &now)
}

// VerifyHistorical re-checks an accepted spec without expiry: a controller
// reloads it after the signatures' validity ended. Removing the root from
// the image still revokes it.
func VerifyHistorical(wire []byte, roots trust.Keyring, id Identity) (Verified, error) {
	return verify(wire, roots, id, nil)
}

func verify(wire []byte, roots trust.Keyring, id Identity, now *time.Time) (Verified, error) {
	if err := id.Validate(); err != nil {
		return Verified{}, err
	}
	var signed Signed
	if err := protocol.DecodeStrict(wire, &signed, MaxSignedBytes); err != nil {
		return Verified{}, fmt.Errorf("decode signed cell spec: %w", err)
	}
	// One signed spec has one wire form, so its digest names it.
	if canonical, err := protocol.EncodeJSON(signed); err != nil || !bytes.Equal(canonical, wire) {
		return Verified{}, fmt.Errorf("%w: signed cell spec is not canonical JSON", ErrInvalid)
	}
	specEnvelope, err := trust.DecodeEnvelope(signed.Spec)
	if err != nil {
		return Verified{}, fmt.Errorf("cell spec envelope: %w", err)
	}
	specPolicy := trust.Policy{MaxLifetime: MaxSpecLifetime, ClockSkew: clockSkew}
	var payload []byte
	rootSigned := len(signed.Delegation) == 0
	switch {
	case rootSigned && now != nil:
		payload, err = trust.VerifyCurrent(specEnvelope, id.Scope(), roots, *now, specPolicy)
	case rootSigned:
		payload, err = trust.VerifyHistorical(specEnvelope, id.Scope(), roots, specPolicy)
	default:
		payload, err = verifyDelegated(signed.Delegation, specEnvelope, roots, id, now, specPolicy)
	}
	if err != nil {
		return Verified{}, fmt.Errorf("verify cell spec signature: %w", err)
	}
	spec, err := Decode(payload)
	if err != nil {
		return Verified{}, err
	}
	if spec.Identity != id || spec.Generation == 0 {
		return Verified{}, fmt.Errorf("%w: signed spec names another identity or generation 0", ErrInvalid)
	}
	return Verified{Spec: spec, RootSigned: rootSigned}, nil
}

delivery-codec.text:
func (c Ed25519Codec) clock() time.Time {
	if c.Now != nil {
		return c.Now()
	}
	return time.Now()
}

func (c Ed25519Codec) policy() (protocol.VerifyPolicy, error) {
	if !nameRE.MatchString(c.Cell) || c.MaxLifetime <= 0 || c.ClockSkew < 0 {
		return protocol.VerifyPolicy{}, fmt.Errorf("%w: signed delivery codec configuration", ErrInvalid)
	}
	return protocol.VerifyPolicy{MaxLifetime: c.MaxLifetime, ClockSkew: c.ClockSkew}, nil
}

func (c Ed25519Codec) Sign(ctx context.Context, payload []byte) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if c.Lifetime <= 0 || c.Lifetime > c.MaxLifetime || len(c.PrivateKey) != ed25519.PrivateKeySize || c.Actor == "" {
		return nil, ErrInvalid
	}
	i, err := DecodeIntent(payload)
	if err != nil {
		return nil, err
	}
	if i.Cell != c.Cell {
		return nil, ErrInvalid
	}
	issued := c.clock().UTC()
	e, err := protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: i.Cell, Kind: intentKind, Actor: c.Actor, OperationID: i.OperationID, Generation: i.Generation, Epoch: i.AuthorityEpoch}, issued, issued.Add(c.Lifetime), c.PrivateKey)
	if err != nil {
		return nil, err
	}
	return protocol.EncodeJSON(e)
}

func (c Ed25519Codec) Verify(ctx context.Context, wire []byte) (VerifiedEnvelope, error) {
	if err := ctx.Err(); err != nil {
		return VerifiedEnvelope{}, err
	}
	var e protocol.Envelope
	if err := protocol.DecodeStrict(wire, &e, MaxIntentBytes+8192); err != nil {
		return VerifiedEnvelope{}, err
	}
	i, err := DecodeIntent(e.Payload)
	if err != nil {
		return VerifiedEnvelope{}, err
	}
	if i.Cell != c.Cell {
		return VerifiedEnvelope{}, ErrInvalid
	}
	trusted, err := c.verifyScopeAt(e, protocol.EnvelopeScope{Region: i.Cell, Kind: intentKind, OperationID: i.OperationID, Generation: i.Generation, Epoch: i.AuthorityEpoch}, c.clock().UTC())
	if err != nil {
		return VerifiedEnvelope{}, err
	}
	return VerifiedEnvelope{Payload: e.Payload, Actor: trusted.Actor}, nil
}

