func newRegionalCluster(t *testing.T, ctx context.Context) *regionalCluster {
	t.Helper()
	ports := reservePorts(t, regionalPeers)
	routes := make([]string, regionalPeers)
	for i, port := range ports {
		routes[i] = "nats-route://" + net.JoinHostPort("127.0.0.1", fmt.Sprint(port))
	}
	storeRoot := t.TempDir()
	cluster := &regionalCluster{configs: make([]natscell.Config, regionalPeers), nodes: make([]*natscell.Runtime, regionalPeers)}
	instances := []string{"one", "two", "three"}
	for i := range regionalPeers {
		cluster.configs[i] = natscell.Config{
			Cell: "lab", Instance: instances[i], Replicas: regionalPeers, Lab: true,
			Embedded: &natscell.Embedded{
				Host: "127.0.0.1", Port: -1, RouteHost: "127.0.0.1", RoutePort: ports[i],
				Routes: natscell.PeerRoutes(routes, routes[i]), StoreDir: filepath.Join(storeRoot, fmt.Sprintf("node-%d", i)),
			},
		}
	}
	t.Cleanup(func() {
		for _, node := range cluster.nodes {
			_ = node.Close()
		}
	})
	return cluster
}

func reservePorts(t *testing.T, count int) []int {
	t.Helper()
	ports := make([]int, count)
	for i := range count {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		addr, ok := listener.Addr().(*net.TCPAddr)
		if !ok {
			_ = listener.Close()
			t.Fatalf("listener address has type %T, want *net.TCPAddr", listener.Addr())
		}
		ports[i] = addr.Port
		if err := listener.Close(); err != nil {
			t.Fatal(err)
		}
	}
	return ports
}

regional-start.text:
func (c *regionalCluster) startAll(ctx context.Context) error {
	for i := range regionalPeers {
		if err := c.start(ctx, i); err != nil {
			return fmt.Errorf("start NATS peer %d: %w", i, err)
		}
	}
	return nil
}

func (c *regionalCluster) start(ctx context.Context, index int) error {
	if c.nodes[index] != nil {
		return fmt.Errorf("NATS peer %d is already running", index)
	}
	runtime, err := natscell.Start(ctx, c.configs[index])
	if err != nil {
		return err
	}
	c.nodes[index] = runtime
	return nil
}

func (c *regionalCluster) stop(index int) error {
	node := c.nodes[index]
	if node == nil {
		return fmt.Errorf("NATS peer %d is not running", index)
	}
	c.nodes[index] = nil
	return node.Close()
}

regional-leader.text:
func (c *regionalCluster) controlStreamLeader(ctx context.Context) (int, error) {
	stream, err := c.nodes[0].JetStream().Stream(ctx, authority.ControlStreamName)
	if err != nil {
		return -1, err
	}
	info, err := stream.Info(ctx)
	if err != nil {
		return -1, err
	}
	// StreamInfo.Cluster.Replicas excludes the responding server, which is the
	// stream leader for this API response. An R3 stream therefore reports its
	// leader separately and the other two peers in Replicas.
	if info.Cluster == nil || info.Cluster.Leader == "" || len(info.Cluster.Replicas) != regionalPeers-1 || info.Config.Replicas != regionalPeers {
		return -1, fmt.Errorf("control stream is not an R3 group: cluster=%+v replicas=%d", info.Cluster, info.Config.Replicas)
	}
	leaderIndex := slices.IndexFunc(c.configs, func(cfg natscell.Config) bool {
		return info.Cluster.Leader == cfg.Cell+"-"+cfg.Instance
	})
	if leaderIndex < 0 {
		return -1, fmt.Errorf("control stream leader %q is not one of the embedded peers", info.Cluster.Leader)
	}
	peerNames := make(map[string]bool, regionalPeers-1)
	for i, cfg := range c.configs {
		if i != leaderIndex {
			peerNames[cfg.Cell+"-"+cfg.Instance] = true
		}
	}
	for _, replica := range info.Cluster.Replicas {
		if replica == nil || !peerNames[replica.Name] {
			return -1, fmt.Errorf("control stream has unexpected or duplicate replica %+v", replica)
		}
		delete(peerNames, replica.Name)
	}
	if len(peerNames) != 0 {
		return -1, fmt.Errorf("control stream replicas do not cover every non-leader peer: remaining=%v", peerNames)
	}
	return leaderIndex, nil
}

func (c *regionalCluster) waitForPeers(ctx context.Context) error {
	for i, node := range c.nodes {
		if node == nil {
			return fmt.Errorf("NATS peer %d is not running", i)
		}
		if err := node.WaitForCluster(ctx, regionalPeers); err != nil {
			return fmt.Errorf("wait for NATS peer %d: %w", i, err)
		}
	}
	return nil
}

nats-config.text:
// Config describes a single regional cell. Every connection requires verified
// TLS and a JWT credential scoped to its regional account.
type Config struct {
	Cell            string    `json:"cell"`
	Instance        string    `json:"instance"`
	Replicas        int       `json:"replicas"`
	ClientRole      string    `json:"client_role,omitempty"`
	URL             string    `json:"url"`
	NKeySeedFile    string    `json:"nkey_seed_file"`
	CredentialsFile string    `json:"credentials_file"`
	TLS             TLSFiles  `json:"tls"`
	Embedded        *Embedded `json:"embedded"`
	// OperatorForward is a transient CLI-only TCP route. Its keys remain the
	// configured controller TLS identities; values are local Bastion forwards.
	OperatorForward map[string]string `json:"-"`
	// ReloadClientMaterial, when set, is consulted on every connect and
	// reconnect so renewed credentials take effect without a process restart.
	// It must keep the startup NATS user key; failures use the startup files.
	ReloadClientMaterial func() (ClientMaterial, error) `json:"-"`
}

nats-validate.text:
func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

