func (a *Adapter) Dispatch(ctx context.Context, request Object) (result Object, err error) {
	defer recoverError(&err)
	role := str(request, "role")
	if role == "service_state" || role == "qualify" {
		label := "source"
		if str(request, "guest_role") == "controller" {
			label = "controller"
