func number(path string) int64 { return integerText(readText(path, 128), path) }
func ioWeight(path, device string) int64 {
	for line := range strings.SplitSeq(strings.TrimSpace(readText(filepath.Join(path, "io.weight"), 16384)), "\n") {
		f := strings.Fields(line)
		if len(f) == 2 && (f[0] == device || f[0] == "default") {
			return integerText(f[1], "io.weight")
		}
	}
	qfail("%s missing numeric I/O weight", path)
	return 0
}
func priorityGroup(path string, cpu, io int64, label string) Object {
	actualCPU := number(filepath.Join(path, "cpu.weight"))
	actualIO := ioWeight(path, "default")
	if actualCPU != cpu || actualIO != io {
		qfail("%s: cpu.weight=%d io.weight=%d expected %d/%d", label, actualCPU, actualIO, cpu, io)
	}
	return Object{"cpu_weight": actualCPU, "io_weight": actualIO}
}
func cpuMax(path string) string {
	f := strings.Fields(readText(filepath.Join(path, "cpu.max"), 128))
	if len(f) != 2 {
		qfail("invalid cpu.max at %s", path)
	}
	return strings.Join(f, " ")
}
func xattr(path, name string) any {
	b := make([]byte, 128)
	n, e := unix.Getxattr(path, name, b)
	if e == unix.ENODATA {
		return nil
	}
	if e != nil {
		qfail("cannot inspect %s on %s: %v", name, path, e)
	}
	return string(b[:n])
}
func oomd(protected, workloads map[string]string) Object {
	o := Object{"omit": Object{}, "avoid": Object{}}
	for label, path := range protected {
		omit, avoid := xattr(path, "user.oomd_omit"), xattr(path, "user.oomd_avoid")
		if omit != "1" || avoid != nil {
			qfail("%s: expected systemd-oomd omit='1' only", label)
		}
		sub(o, "omit")[label] = omit
		sub(o, "avoid")[label] = avoid
	}
	for label, path := range workloads {
		omit, avoid := xattr(path, "user.oomd_omit"), xattr(path, "user.oomd_avoid")
		if omit != nil || avoid != nil {
			qfail("%s workload must stay eligible for systemd-oomd", label)
		}
		sub(o, "omit")[label] = omit
		sub(o, "avoid")[label] = avoid
	}
	return o
}
func ValidateBakedProfile(wire []byte, mode os.FileMode, uid, gid uint32, links uint64, profile string, reserve int64) (result Object, err error) {
	defer recoverError(&err)
	if !mode.IsRegular() || mode.Perm() != 0644 || uid != 0 || gid != 0 || links != 1 {
		qfail("baked runtime-priority profile must be a root-owned regular 0644 file with one link")
	}
	if len(wire) == 0 || len(wire) > 4096 {
		qfail("baked runtime-priority profile has invalid size")
	}
	var o Object
	if e := jsonUnmarshal(wire, &o); e != nil {
		qfail("baked runtime-priority profile is invalid JSON: %v", e)
	}
	if !exact(o, "version", "profile_id", "system_reserve_bytes") {
		qfail("baked runtime-priority profile has an unsupported schema")
	}
	expected := Object{"version": 1, "profile_id": profile, "system_reserve_bytes": reserve}
	if !same(o, expected) {
		qfail("baked runtime-priority profile ID/reserve differs from the requested signed placement profile")
	}
	canonical := fmt.Sprintf(`{"version":1,"profile_id":%s,"system_reserve_bytes":%d}`, Canonical(profile), reserve)
	if string(wire) != canonical {
		qfail("baked runtime-priority profile is not canonical JSON")
	}
	result = expected
	result["sha256"] = Hash(wire)
	return
}

qualifier-memory.text:
func (p *Qualifier) memoryBudget(values Object, service string) Object {
	role := str(p.Args, "role")
	prefix := "expected_memory_"
	if role == "controller" {
		prefix = "expected_controller_memory_"
	}
	mi, lo := n(p.Args, prefix+"min_bytes"), n(p.Args, prefix+"low_bytes")
	smi, slo, reserve, alloc := n(p.Args, "expected_system_slice_memory_min_bytes"), n(p.Args, "expected_system_slice_memory_low_bytes"), n(p.Args, "system_reserve_bytes"), n(p.Args, "allocatable_memory_bytes")
	for _, v := range []int64{mi, lo, smi, slo, reserve, alloc} {
		if v <= 0 || v%int64(os.Getpagesize()) != 0 {
			qfail("memory profile values must be positive, page-aligned bytes")
		}
	}
	if mi > lo || smi < mi || slo < lo || smi > slo || slo > reserve {
		qfail("%s and system.slice memory floors exceed the signed reserve", role)
	}
	if str(values, "MemoryMin") != strconv.FormatInt(mi, 10) || str(values, "MemoryLow") != strconv.FormatInt(lo, 10) {
		qfail("%s unit memory floors differ from profile", role)
	}
	system := filepath.Dir(service)
	if filepath.Base(system) != "system.slice" {
		qfail("%s unit is not a child of system.slice", role)
	}
	actual := Object{role + "_memory_min_bytes": number(filepath.Join(service, "memory.min")), role + "_memory_low_bytes": number(filepath.Join(service, "memory.low")), "system_slice_memory_min_bytes": number(filepath.Join(system, "memory.min")), "system_slice_memory_low_bytes": number(filepath.Join(system, "memory.low"))}
	if n(actual, role+"_memory_min_bytes") != mi || n(actual, role+"_memory_low_bytes") != lo || n(actual, "system_slice_memory_min_bytes") != smi || n(actual, "system_slice_memory_low_bytes") != slo {
		qfail("%s/system.slice memory protections differ from profile", role)
	}
	if role == "host" {
		super := filepath.Join(service, "supervisor")
		actual["supervisor_memory_min_bytes"] = number(filepath.Join(super, "memory.min"))
		actual["supervisor_memory_low_bytes"] = number(filepath.Join(super, "memory.low"))
		if n(actual, "supervisor_memory_min_bytes") != mi || n(actual, "supervisor_memory_low_bytes") != lo {
			qfail("host supervisor lacks service memory floors")
		}
	}
	ancestors := []any{}
	for cursor := system; cursor != p.CgroupRoot; cursor = filepath.Dir(cursor) {
		if !inside(cursor, p.CgroupRoot) {
			qfail("cgroup ancestor escaped unified root")
		}
		a, b := number(filepath.Join(cursor, "memory.min")), number(filepath.Join(cursor, "memory.low"))
		if a < mi || b < lo {
			qfail("ancestor %s below required service reservation", cursor)
		}
		ancestors = append(ancestors, Object{"service": role, "cgroup": cursor, "memory_min_bytes": a, "memory_low_bytes": b})
	}
	mem := regexp.MustCompile(`(?m)^MemTotal:\s+(\d+)\s+kB`).FindStringSubmatch(readText(filepath.Join(p.ProcRoot, "meminfo"), 16384))
	if len(mem) != 2 {
		qfail("cannot read physical memory total")
	}
	available := integerText(mem[1], "MemTotal") * 1024
	for cursor := service; ; cursor = filepath.Dir(cursor) {
		if cursor != p.CgroupRoot && !inside(cursor, p.CgroupRoot) {
			qfail("cgroup ancestor escaped unified root")
		}
		s := strings.TrimSpace(readText(filepath.Join(cursor, "memory.max"), 128))
		if s != "max" {
			available = min(available, integerText(s, "ancestor memory.max"))
		}
		if cursor == p.CgroupRoot {
			break
		}
	}
	if alloc > available-reserve {
		qfail("signed allocatable+reserve exceeds physical/ancestor limit")
	}
	actual["allocatable_memory_bytes"] = alloc
	actual["system_reserve_bytes"] = reserve
	actual["available_physical_and_ancestor_memory_bytes"] = available
	actual["ancestor_protections"] = ancestors
	return actual
}

qualifier-run.text:
func (p *Qualifier) Run(ctx context.Context) (result Object, err error) {
	defer recoverError(&err)
	p.roots()
	role := str(p.Args, "role")
	if role != "host" && role != "controller" {
		qfail("role must be host or controller")
	}
	name := HostUnit
	if role == "controller" {
		name = ControllerUnit
		if p.Args["database_pid"] != nil {
			qfail("controller guest cannot qualify a TerraBase PID")
		}
	}
	if v := str(p.Args, role+"_unit"); v != "" {
		name = v
	}
	version := strings.Split(p.command(ctx, []string{"systemctl", "--version"}), "\n")[0]
	match := regexp.MustCompile(`^systemd\s+(\d+)`).FindStringSubmatch(version)
	if len(match) != 2 || integerText(match[1], "systemd version") < 255 {
		qfail("target requires systemd 255 or newer")
	}
	values := p.unit(ctx, name)
	var profile Object
	var e error
	if p.BakedProfile != nil {
		profile, e = p.BakedProfile()
	} else {
		profile, e = p.VerifyBakedProfile()
	}
	if e != nil {
		panic(e)
	}
	pid := unitPriority(name, values, role == "host")
	service := filepath.Join(p.CgroupRoot, str(values, "ControlGroup"))
	process := p.process(ctx, pid, role, true)
	expected := service
	if role == "host" {
		expected = filepath.Join(service, "supervisor")
	}
	if str(process, "cgroup") != expected {
		qfail("%s process outside exact protected cgroup", role)
	}
	weights := priorityGroup(service, 10000, 10000, role+" service")
	memory := p.memoryBudget(values, service)
	var cgroups, processes, policy Object
	if role == "controller" {
		cap := cpuMax(service)
		if !strings.HasPrefix(cap, "max ") {
			qfail("controller service has a CPU quota")
		}
		cgroups = Object{"controller_service": service, "controller_weights": weights, "controller_cpu_max": cap}
		processes = Object{"controller": process}
		policy = oomd(map[string]string{"controller_service": service}, nil)
	} else {
		cgroups, processes, policy = p.hostRuntime(ctx, pid, service, process, weights)
	}
	sample, e := p.CaptureMemorySample(map[string]string{role + "_service": service, "system_slice": filepath.Dir(service)}, version)
	if e != nil {
		panic(e)
	}
	unitWire := readText(filepath.Join(p.UnitRoot, name), 1<<20)
	binary, _, e := readNoFollow(p.Executable, MaxProbeBytes)
	if e != nil {
		qfail("cannot hash qualifier binary: %v", e)
	}
	result = Object{"status": "PASS", "guest_role": role, "repository_revision": nil, "qualifier_sha256": Hash(binary), "baked_runtime_priority_profile": profile, "systemd_version": version, "units": Object{role: values}, "processes": processes, "cgroups": cgroups, "memory_usage_sample": sample, "memory_profile": memory, "systemd_oomd_policy": policy, "unit_sha256": Object{name: Hash([]byte(unitWire))}}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		result[k] = p.Args[k]
	}
	return
}

qualifier-sample.text:
func (p *Qualifier) CaptureMemorySample(cgroups map[string]string, version string) (sample Object, err error) {
	defer recoverError(&err)
	p.roots()
	started := utcNow()
	rows := Object{}
	rootFD, e := unix.Open(p.CgroupRoot, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		qfail("cannot anchor cgroup memory sample: %v", e)
	}
	defer unix.Close(rootFD)
	openDirectory := func(path string) (*os.File, error) {
		if !inside(path, p.CgroupRoot) {
			qfail("memory sample escaped cgroup root")
		}
		relative, e := filepath.Rel(p.CgroupRoot, path)
		if e != nil {
			return nil, e
		}
		fd, e := unix.Openat2(rootFD, relative, &unix.OpenHow{Flags: unix.O_RDONLY | unix.O_DIRECTORY | unix.O_CLOEXEC, Resolve: unix.RESOLVE_BENEATH | unix.RESOLVE_NO_SYMLINKS | unix.RESOLVE_NO_MAGICLINKS})
		if e != nil {
			return nil, e
		}
		return os.NewFile(uintptr(fd), path), nil
	}
	sameDirectory := func(path string, meta os.FileInfo) bool {
		named, e := openDirectory(path)
		if e != nil {
			return false
		}
		defer named.Close()
		current, e := named.Stat()
		return e == nil && os.SameFile(meta, current)
	}
	var systemDir *os.File
	var systemMeta os.FileInfo
	for _, scope := range slices.Sorted(maps.Keys(cgroups)) {
		path := cgroups[scope]
		if !inside(path, p.CgroupRoot) {
			qfail("%s memory sample escaped cgroup root", scope)
		}
		dir, e := openDirectory(path)
		if e != nil {
			qfail("cannot capture %s cgroup memory: %v", scope, e)
		}
		defer dir.Close()
		fd := int(dir.Fd())
		func() {
			meta, e := dir.Stat()
			if e != nil {
				qfail("cannot inspect cgroup directory: %v", e)
			}
			if p.AfterDirectoryOpen != nil {
				p.AfterDirectoryOpen(path)
			}
			check := func(stage string) {
				if !sameDirectory(path, meta) {
					qfail("%s memory sample cgroup changed %s capture", scope, stage)
				}
			}
			check("before")
			read := func(name string, max int64) string {
				f, e := unix.Openat(fd, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				file := os.NewFile(uintptr(f), name)
				defer file.Close()
				b, e := io.ReadAll(io.LimitReader(file, max+1))
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				if int64(len(b)) > max {
					qfail("%s %s exceeds its fixed evidence bound", scope, name)
				}
				return string(b)
			}
			current, peak, stat := read("memory.current", 128), read("memory.peak", 128), read("memory.stat", 16384)
			check("during")
			rows[scope] = Object{"cgroup_path": path, "cgroup_inode": meta.Sys().(*syscall.Stat_t).Ino, "memory_current_raw": current, "memory_current_bytes": integerText(current, "memory.current"), "memory_peak_raw": peak, "memory_peak_bytes": integerText(peak, "memory.peak"), "memory_stat_raw": stat, "memory_stat_sha256": Hash([]byte(stat))}
			if scope == "system_slice" {
				systemDir, systemMeta = dir, meta
			}
		}()
	}
	system := cgroups["system_slice"]
	if systemDir == nil || !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed before child enumeration")
	}
	children := []string{}
	size := 0
	for {
		entries, e := systemDir.ReadDir(1)
		if e == io.EOF {
			break
		}
		if e != nil {
			qfail("cannot enumerate system.slice: %v", e)
		}
		entry := entries[0]
		if p.ChildVisited != nil {
			p.ChildVisited(entry.Name())
		}
		if entry.Type()&os.ModeSymlink != 0 {
			qfail("system.slice contains symlink while child scopes sampled")
		}
		if !entry.IsDir() {
			continue
		}
		size += len(entry.Name())
		if len(children) >= 256 || size > 16384 {
			qfail("system.slice child-cgroup list exceeds its fixed evidence bound")
		}
		children = append(children, entry.Name())
	}
	if !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed during child enumeration")
	}
	slices.Sort(children)
	var u unix.Utsname
	if e := unix.Uname(&u); e != nil {
		qfail("cannot read kernel release: %v", e)
	}
	release := string(u.Release[:])
	release, _, _ = strings.Cut(release, "\x00")
	sample = Object{"schema": MemorySampleSchema, "guest_role": str(p.Args, "role"), "host_boot_id": strings.TrimSpace(readText(filepath.Join(p.ProcRoot, "sys/kernel/random/boot_id"), 128)), "kernel_release": release, "systemd_version": version, "started_at_utc": started, "finished_at_utc": utcNow(), "scopes": rows, "system_slice_direct_child_cgroups": children}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		sample[k] = p.Args[k]
	}
	sample["sample_sha256"] = Hash(Canonical(sample))
	return
}

common-read.text:
func readNoFollow(path string, maximum int64) ([]byte, os.FileInfo, error) {
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		return nil, nil, e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	before, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	if !before.Mode().IsRegular() || before.Size() > maximum {
		return nil, nil, fmt.Errorf("%s must be a regular file no larger than %d bytes", path, maximum)
	}
	wire, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return nil, nil, e
	}
	after, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	named, e := os.Lstat(path)
	if e != nil {
		return nil, nil, e
	}
	if int64(len(wire)) > maximum || !os.SameFile(before, after) || !os.SameFile(before, named) || before.Size() != after.Size() || before.ModTime() != after.ModTime() {
		return nil, nil, fmt.Errorf("%s changed during readback", path)
	}
	return wire, before, nil
}

common-write.text:
func writeJSON(path string, v any, exclusive bool) error {
	flags := os.O_WRONLY | os.O_CREATE | os.O_TRUNC
	if exclusive {
		flags = os.O_WRONLY | os.O_CREATE | os.O_EXCL
	}
	fd, e := unix.Open(path, flags|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0600)
	if e != nil {
		return e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	b, e := json.Marshal(v, json.Deterministic(true))
	if e != nil {
		return e
	}
	if _, e = f.Write(append(b, '\n')); e != nil {
		return e
	}
	return f.Sync()
}
func parseProperties(raw, label string) Object {
	o := Object{}
	for line := range strings.SplitSeq(strings.TrimSpace(raw), "\n") {
		k, v, ok := strings.Cut(line, "=")
		if !ok || k == "" {
			fail("%s malformed systemd property", label)
		}
		if _, exists := o[k]; exists {
			fail("%s repeats systemd property %s", label, k)
		}
		o[k] = v
	}
	return o
}
func readText(path string, maximum int64) string {
	b, _, e := readNoFollow(path, maximum)
	if e != nil {
		fail("cannot read %s: %v", path, e)
	}
	return string(b)
}

cgroup-validator.text:
func rawJSON(raw, label, hash string, max int) any {
	if len(raw) > max {
		fail("%s exceeds its %d-byte evidence bound", label, max)
	}
	if hash != "" && (!hashRE.MatchString(hash) || Hash([]byte(raw)) != hash) {
		fail("%s hash absent or does not match retained bytes", label)
	}
	var value any
	if e := jsonUnmarshal([]byte(raw), &value); e != nil {
		fail("%s invalid JSON: %v", label, e)
	}
	return value
}
func cgroupFilePath(path string) string {
	if !safePath(path) || path == "/" || inside(path, CgroupRoot) {
		fail("managed report process_cgroup is not a safe cgroup-root-relative path")
	}
	return filepath.Join(CgroupRoot, path)
}
func QualifiedRoleCgroups(nativeReport, databaseReport string) (native, database, role string, err error) {
	defer recoverError(&err)
	native, database, role = qualifiedRoleCgroups(nativeReport, databaseReport)
	return
}
func qualifiedRoleCgroups(nativeReport, databaseReport string) (string, string, string) {
	if !safePath(nativeReport) || !inside(nativeReport, CgroupRoot) {
		fail("qualifier native runner cgroup is not safely below the cgroup root")
	}
	database := cgroupFilePath(databaseReport)
	rel, e := filepath.Rel(nativeReport, database)
	if e != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		fail("TerraBase cgroup is not below measured native runner")
	}
	if rel == "." || strings.Contains(rel, "/") {
		fail("TerraBase cgroup must be a direct native role child")
	}
	return nativeReport, database, rel
}

report-validator.text:
func ValidateReportEvidence(evidence, request Object, observed string, member, previous Object) (result Object, err error) {
	defer recoverError(&err)
	hosts, ok := rawJSON(text(evidence["operator_hosts_json"], "operator hosts JSON"), "operator hosts JSON", str(evidence, "operator_hosts_sha256"), 1<<20).([]any)
	if !ok {
		fail("operator hosts output must be actual HostStatus JSON array")
	}
	sampled := timestamp(observed, "operator hosts observation time")
	witnesses := sub(evidence, "process_witnesses")
	if !exact(witnesses, "source", "peer") {
		fail("operator hosts adapter must witness both managed member processes")
	}
	selected := Object{}
	for _, label := range []string{"source", "peer"} {
		expected := sub(member, label)
		var host Object
		matches := 0
		for _, v := range hosts {
			row := obj(v, "HostStatus")
			registration, ok := row["registration"].(map[string]any)
			if !ok {
				continue
			}
			binding, ok := registration["managed_member"].(map[string]any)
			if ok && registration["cell"] == expected["cell"] && registration["node"] == expected["node"] && registration["environment"] == expected["environment"] && same(binding["scope"], expected["scope"]) {
				matches++
				host = row
			}
		}
		if matches != 1 {
			fail("operator hosts output has %d exact %s registrations", matches, label)
		}
		if host["verified"] != false {
			fail("read-only operator HostStatus.verified must remain false")
		}
		registration := sub(host, "registration")
		expires := timestamp(host["session_expires_at"], label+" session expiry")
		if !expires.After(sampled) {
			fail("%s host session expired at observation time", label)
		}
		reports, ok := host["reports"].([]any)
		if !ok {
			fail("%s HostStatus.reports not array", label)
		}
		var report Object
		matches = 0
		for _, v := range reports {
			r, ok := v.(map[string]any)
			if ok && r["cell"] == expected["cell"] && r["node"] == expected["node"] && r["environment"] == expected["environment"] && r["role"] == expected["role"] {
				report = r
				matches++
			}
		}
		if matches != 1 {
			fail("%s HostStatus does not contain one exact managed-role report", label)
		}
		when := timestamp(report["observed_at"], label+" report.observed_at")
		age := sampled.Sub(when)
		if age < -2*time.Second || age >= 30*time.Second {
			fail("%s accepted report is future-dated or at least 30 seconds old", label)
		}
		old, _ := previous[label].(map[string]any)
		if old != nil && !when.After(reportTime(old, "report_time")) {
			fail("%s report observed_at did not strictly advance", label)
		}
		if str(report, "state") != "running" {
			fail("%s actual report state=%q error=%v", label, str(report, "state"), report["error"])
		}
		num(report["generation"], label+" report generation", 1)
		num(registration["generation"], label+" registration generation", 1)
		num(report["epoch"], label+" report epoch", 1)
		if !hashRE.MatchString(str(report, "digest")) || str(report, "session_id") == "" {
			fail("%s report lacks accepted desired/session identity", label)
		}
		if old != nil {
			if !same(registration["generation"], old["registration_generation"]) || !same(report["generation"], old["generation"]) || report["digest"] != old["digest"] {
				fail("%s registration or desired report identity changed during D15", label)
			}
			restart := label == "source" && str(sub(request, "pressure"), "scenario") == "host_manager_sigkill" && str(request, "phase") == "post_recovery"
			if !restart && (report["session_id"] != old["session_id"] || !same(report["epoch"], old["epoch"])) {
				fail("%s host session identity changed without host-manager restart", label)
			}
		}
		managed := sub(report, "managed")
		binding, registered := sub(managed, "member"), sub(registration, "managed_member")
		if !exact(binding, "scope", "host_attempt") || !exact(registered, "scope", "host_attempt") || !same(binding["scope"], expected["scope"]) || !same(registered["scope"], expected["scope"]) || !same(binding["host_attempt"], registered["host_attempt"]) || !same(managed["authority"], expected["authority"]) || str(managed, "process_start") == "" || !processNonceRE.MatchString(str(managed, "process_boot_id")) || managed["storage_recovered"] != true || managed["listener_ready"] != true {
			fail("%s accepted managed report lacks exact process/mount readiness", label)
		}
		num(binding["host_attempt"], "host attempt", 1)
		num(managed["process_pid"], "managed process PID", 2)
		proof := validateProof(report, expected, label)
		w := sub(witnesses, label)
		if !exact(w, "pid", "stat_raw", "cgroup_raw", "host_boot_id") {
			fail("%s raw process witness has unexpected fields", label)
		}
		pid, start := procStatIdentity(text(w["stat_raw"], "process stat witness"))
		group := procCgroupPath(text(w["cgroup_raw"], "process cgroup witness"))
		if n(w, "pid") != n(managed, "process_pid") || pid != n(w, "pid") || start != str(managed, "process_start") || filepath.Join(CgroupRoot, group) != cgroupFilePath(str(managed, "process_cgroup")) {
			fail("%s raw process witness differs from accepted managed report", label)
		}
		boot := str(w, "host_boot_id")
		if !uuidRE.MatchString(boot) {
			fail("%s host boot ID not canonical UUID", label)
		}
		identity := Object{"pid": managed["process_pid"], "start": managed["process_start"], "nonce": managed["process_boot_id"], "cgroup": managed["process_cgroup"]}
		if old != nil {
			oldID := sub(old, "managed_identity")
			phase, scenario := str(request, "phase"), str(sub(request, "pressure"), "scenario")
			mayRestart := label == "source" && (phase == "post_recovery" || phase == "after" || phase == "after_write") && (scenario == "terrabase_process" || scenario == "terrabase_oom")
			if !mayRestart && (!same(oldID["pid"], identity["pid"]) || oldID["start"] != identity["start"] || oldID["nonce"] != identity["nonce"]) {
				fail("%s managed process identity changed outside recovery scenario", label)
			}
			if boot != str(old, "host_boot_id") {
				fail("%s host boot ID changed during pressure scenario", label)
			}
		}
		selected[label] = Object{"host": host, "report": report, "proof": proof, "report_time": when, "session_expires_at": expires, "verified": false, "registration_generation": registration["generation"], "generation": report["generation"], "digest": report["digest"], "session_id": report["session_id"], "epoch": report["epoch"], "managed_identity": identity, "host_boot_id": boot}
	}
	return Object{"raw": hosts, "members": selected, "process_witnesses": witnesses}, nil
}

database-validator.text:
func ValidateDatabaseWire(evidence, request, member Object) (result Object, err error) {
	defer recoverError(&err)
	scope, document := sub(sub(member, "source"), "scope"), sub(member, "document")
	prefix := fmt.Sprintf("/v1/tenants/%s/databases/%s/shards/%d", str(scope, "tenant_id"), str(scope, "database_id"), n(scope, "shard_id"))
	if str(evidence, "write_path") != prefix+"/transactions" || str(evidence, "peer_read_path") != fmt.Sprintf("%s/collections/%s/documents/%s", prefix, str(document, "collection_id"), str(request, "document_id")) {
		fail("database adapter did not use exact alpha transaction and cross-member point routes")
	}
	if evidence["document_id"] != request["document_id"] {
		fail("database adapter read different document than transaction operation")
	}
	transaction := obj(rawJSON(text(evidence["transaction_request_raw"], "transaction request"), "database transaction request", str(evidence, "transaction_request_sha256"), 65536), "transaction request")
	writes, ok := transaction["writes"].([]any)
	if !exact(transaction, "version", "transaction_id", "writes") || n(transaction, "version") != 1 || !same(transaction["transaction_id"], request["transaction_id"]) || !ok || len(writes) != 1 {
		fail("transaction request does not match alpha v1 document write request")
	}
	expectedDocument := Object{str(document, "utf8_field"): strconv.FormatInt(n(request, "value"), 10)}
	expected := Object{"collection": document["collection_id"], "document": request["document_id"], "observed": []any{}, "value": Object{"kind": "live", "document": expectedDocument}}
	if !same(writes[0], expected) {
		fail("transaction request bytes do not bind exact scoped document and value")
	}
	receipt := obj(rawJSON(text(evidence["write_receipt_raw"], "write receipt"), "database write receipt", str(evidence, "write_receipt_sha256"), 65536), "write receipt")
	if !exact(receipt, "version", "durability", "transaction_id", "event", "commit_sequence") {
		fail("write receipt does not match alpha transaction ACK shape")
	}
	if n(receipt, "version") != 1 || str(receipt, "durability") != "object_durable" {
		fail("write receipt did not acknowledge ObjectDurable")
	}
	if !same(receipt["transaction_id"], request["transaction_id"]) {
		fail("ObjectDurable receipt transaction ID differs from exact write request")
	}
	commit := str(receipt, "commit_sequence")
	if !decimalRE.MatchString(commit) {
		fail("ObjectDurable commit_sequence must remain opaque decimal string")
	}
	event := sub(receipt, "event")
	if !exact(event, "database", "shard", "replica", "incarnation", "sequence") {
		fail("receipt event does not match alpha scoped event identity")
	}
	for k, want := range (Object{"database": scope["database_id"], "shard": strconv.FormatInt(n(scope, "shard_id"), 10), "replica": scope["member_id"], "incarnation": scope["incarnation"]}) {
		if event[k] != want {
			fail("ObjectDurable receipt event scope/origin differs from signed source member")
		}
	}
	sequence := integerText(text(event["sequence"], "ObjectDurable event sequence"), "ObjectDurable event sequence")
	if sequence < 1 {
		fail("ObjectDurable event.sequence must be positive decimal string")
	}
	point := obj(rawJSON(text(evidence["peer_read_raw"], "peer read"), "peer point read", str(evidence, "peer_read_sha256"), 65536), "peer point read")
	siblings, ok := point["siblings"].([]any)
	if n(point, "version") != 1 || str(point, "state") != "value" || !ok {
		fail("cross-member point read did not return alpha value point")
	}
	matches := 0
	for _, v := range siblings {
		s, ok := v.(map[string]any)
		if !ok || !same(s["event"], event) {
			continue
		}
		if str(s, "kind") != "live" || str(s, "schema_generation") != strconv.FormatInt(n(document, "schema_generation"), 10) || s["schema_digest"] != document["schema_digest"] || !same(s["document"], expectedDocument) {
			fail("peer read event matches receipt but document schema/value does not")
		}
		matches++
	}
	if matches != 1 {
		fail("peer read does not contain exactly one sibling matching the ObjectDurable event")
	}
	return Object{"receipt": receipt, "event": event, "point": point, "event_sequence": sequence, "commit_sequence_opaque": commit}, nil
}

validate-role.text:
func (r *Runner) ValidateRole(role, phase string, request, response Object) (err error) {
	defer recoverError(&err)
	r.validateRole(role, phase, request, response)
	return
}
func (r *Runner) validateRole(role, phase string, request, response Object) {
	evidence := sub(response, "evidence")
	observed := str(response, "observed_at_utc")
	if e := r.ValidateActiveObservation(role, phase, observed); e != nil {
		panic(e)
	}
	switch role {
	case "target_identity":
		r.validateTarget(evidence)
	case "host_status":
		snapshot, e := ValidateReportEvidence(evidence, request, observed, r.member(), r.stateObject("previous_host_rows"))
		if e != nil {
			panic(e)
		}
		members := sub(snapshot, "members")
		previous := r.stateObject("previous_host_rows")
		for label, v := range members {
			if old, ok := previous[label].(map[string]any); ok {
				validatePrevious(snapshot, label, old, request)
			}
			previous[label] = v
		}
		if len(r.stateObject("baseline_host_rows")) == 0 {
			r.State["baseline_host_rows"] = clone(members)
		}
		r.State["host_snapshot"] = snapshot
		if event, ok := r.State["last_event"].(map[string]any); ok {
			assertEventCovered(snapshot, r.member(), event, n(sub(r.State, "last_database_receipt"), "event_sequence"))
			r.State["last_event"] = nil
		}
	case "service_state":
		r.validateServices(evidence, request, observed, phase)
	case "qualify":
		r.validateQualifier(evidence, request, observed, phase)
	case "database_progress":
		receipt, e := ValidateDatabaseWire(evidence, request, r.member())
		if e != nil {
			panic(e)
		}
		event := sub(receipt, "event")
		origin := strings.Join([]string{str(event, "database"), str(event, "shard"), str(event, "replica"), str(event, "incarnation")}, "/")
		sequences := r.stateObject("last_event_sequence_by_origin")
		old := int64(0)
		if sequences[origin] != nil {
			old = num(sequences[origin], "prior event sequence", 0)
		}
		if n(receipt, "event_sequence") <= old {
			fail("ObjectDurable event sequence did not advance for exact origin/scope")
		}
		sequences[origin] = receipt["event_sequence"]
		r.State["last_database_receipt"], r.State["last_event"] = receipt, event
	case "pressure_start", "pressure_status":
		r.validatePressure(role, evidence, response, request)
	case "failure_inject":
		action := sub(evidence, "action_receipt")
		if !exact(action, "target_process", "signal", "requested_at_utc", "completed_at_utc", "exit_status") || !same(action["target_process"], request["target_process"]) || str(action, "signal") != "SIGKILL" || n(action, "exit_status") != 0 {
			fail("failure action did not target exact current TerraBase/host manager process")
		}
		sent, asked, done, obs := timestamp(request["sent_at_utc"], "failure sent"), timestamp(action["requested_at_utc"], "failure request"), timestamp(action["completed_at_utc"], "failure complete"), timestamp(observed, "failure observation")
		if sent.After(asked) || asked.After(done) || done.After(obs) {
			fail("failure timestamps outside exact request window")
		}
		r.State["failure_injection_at"], r.State["failure_observed"] = done, true
	case "kernel_oom_evidence":
		r.validateOOM(evidence, request, observed)
	case "pressure_stop":
		if evidence["handle"] != r.State["handle"] || !same(evidence["pressure_cgroup_process_pids"], []any{}) || str(evidence, "pressure_cgroup_procs_raw") != "" {
			fail("pressure stop did not prove exact workload cgroup empty")
		}
	case "cleanup_verify":
		cleanup := sub(evidence, "cleanup")
		if str(cleanup, "pressure_cgroup_procs_raw") != "" || !same(cleanup["pressure_child_cgroups"], []any{}) || !same(cleanup["scratch_paths"], []any{}) {
			fail("cleanup did not prove empty workload cgroup and removed scratch paths")
		}
		if intent, ok := r.State["oom_restore_intent"].(map[string]any); ok {
			restored := cleanup["oom_restore_verified"] == true && same(cleanup["oom_restore_target"], intent["target"]) && same(cleanup["oom_restore_cgroup_inode"], intent["cgroup_inode"]) && same(cleanup["current_database_memory_max_bytes"], r.qualification()["database_memory_max_bytes"])
			if !restored {
				reason := str(cleanup, "oom_restore_unresolved_reason")
				if reason == "" {
					reason = "cleanup could not verify exact native role cap"
				}
				r.State["oom_restore_unresolved_reason"] = reason
				fail("cleanup left native OOM restore obligation unresolved")
			}
			r.State["oom_restore_cleanup_verified"], r.State["oom_restore_unresolved_reason"] = true, nil
		}
	default:
		fail("unsupported adapter role %s", role)
	}
}

validate-target.text:
func (r *Runner) validateTarget(e Object) {
	if !exact(e, "operator_hosts_json", "operator_hosts_sha256", "architecture_by_member", "source_oci_metadata", "controller_oci_metadata") {
		fail("target identity evidence does not match alpha source schema")
	}
	hosts, ok := rawJSON(text(e["operator_hosts_json"], "target hosts JSON"), "target identity hosts JSON", str(e, "operator_hosts_sha256"), 1<<20).([]any)
	if !ok {
		fail("target identity HostStatus evidence must be array")
	}
	if !same(e["architecture_by_member"], Object{"source": "aarch64", "peer": "aarch64", "controller": "aarch64"}) {
		fail("SSH targets do not report pinned aarch64 architecture")
	}
	targets := sub(sub(sub(r.Manifest, "transport"), "ssh"), "targets")
	regs := Object{}
	regions := catalog.Map()
	for _, label := range []string{"source", "peer"} {
		want := sub(r.member(), label)
		count := 0
		for _, v := range hosts {
			host := obj(v, "target HostStatus")
			reg, ok := host["registration"].(map[string]any)
			if !ok {
				continue
			}
			binding, ok := reg["managed_member"].(map[string]any)
			if ok && reg["cell"] == want["cell"] && reg["node"] == want["node"] && reg["environment"] == want["environment"] && same(binding["scope"], want["scope"]) {
				if host["verified"] != false {
					fail("target identity lacks read-only admitted HostStatus")
				}
				oci := sub(reg, "managed_oci")
				if oci["instance_id"] != sub(targets, label)["oci_instance_id"] || regions[str(oci, "region")] == "" {
					fail("%s HostStatus does not match pinned OCI instance/region", label)
				}
				regs[label] = reg
				count++
			}
		}
		if count != 1 {
			fail("target identity lacks one read-only admitted %s HostStatus", label)
		}
	}
	region := regions[str(sub(sub(regs, "source"), "managed_oci"), "region")]
	for label, idKey := range map[string]string{"source": "identity", "controller": "controller_identity"} {
		metadata := sub(e, label+"_oci_metadata")
		id := sub(r.Manifest, idKey)
		if !exact(metadata, "instance_id", "image_id", "region", "shape") || metadata["instance_id"] != id["oci_instance_id"] || metadata["image_id"] != id["image_id"] || str(metadata, "region") != region || str(metadata, "shape") == "" {
			fail("live OCI metadata does not match the pinned %s instance, image and region", label)
		}
	}
}

failure-target.text:
func (r *Runner) FailureTarget() (target Object, err error) {
	defer recoverError(&err)
	target = r.failureTarget()
	return
}
func (r *Runner) terrabaseTarget() Object {
	snapshot := r.snapshot()
	row := sub(sub(snapshot, "members"), "source")
	w := sub(sub(snapshot, "process_witnesses"), "source")
	managed := sub(sub(row, "report"), "managed")
	return Object{"kind": "terrabase", "node": sub(r.member(), "source")["node"], "pid": managed["process_pid"], "process_start": managed["process_start"], "process_nonce": managed["process_boot_id"], "cgroup": managed["process_cgroup"], "host_boot_id": w["host_boot_id"], "stat_raw": w["stat_raw"], "cgroup_raw": w["cgroup_raw"]}
}
func (r *Runner) failureTarget() Object {
	scenario := str(r.pressure(), "scenario")
	source := sub(sub(r.snapshot(), "members"), "source")
	maxAge := time.Duration(n(sub(r.Manifest, "adapter_contract"), "target_witness_max_age_ms")) * time.Millisecond
	age := time.Since(reportTime(source, "report_time"))
	if age < 0 || age > maxAge {
		fail("accepted TerraBase report/process witness stale before SIGKILL")
	}
	if scenario == "terrabase_process" || scenario == "terrabase_oom" {
		if scenario == "terrabase_oom" {
			fail("TerraBase OOM observed from kernel; pressure workers are not injected victims")
		}
		target := r.terrabaseTarget()
		native, db, _ := qualifiedRoleCgroups(str(r.State, "native_runner_path"), str(target, "cgroup"))
		if native != str(r.State, "native_runner_path") || db != str(r.State, "database_cgroup_path") {
			fail("TerraBase SIGKILL target differs from the qualifier-pinned native role cgroup")
		}
		return target
	}
	if scenario != "host_manager_sigkill" {
		fail("failure target not approved scenario")
	}
	unit := sub(r.stateObject("service_snapshot"), HostUnit)
	unitAge := time.Since(reportTime(unit, "observed_at"))
	if unitAge < 0 || unitAge > maxAge {
		fail("host manager and accepted managed report witnesses stale before SIGKILL")
	}
	return Object{"kind": "host_manager", "unit": HostUnit, "pid": unit["main_pid"], "process_start": unit["process_start"], "cgroup": strings.TrimSuffix(str(unit, "control_group"), "/") + "/supervisor", "host_boot_id": source["host_boot_id"], "stat_raw": unit["process_stat_raw"], "cgroup_raw": unit["process_cgroup_raw"]}
}

compare-services.text:
func (r *Runner) CompareServices(current Object, phase string) (err error) {
	defer recoverError(&err)
	for unit, value := range current {
		now := obj(value, "service snapshot")
		old := sub(r.stateObject("previous_services"), unit)
		if old["control_group"] != now["control_group"] {
			fail("%s systemd cgroup changed during D15 scenario", unit)
		}
		restart := unit == HostUnit && str(r.pressure(), "scenario") == "host_manager_sigkill" && slices.Contains([]string{"post_recovery", "after", "after_write"}, phase) && r.State["failure_observed"] == true
		if restart {
			baseline := sub(r.stateObject("baseline_services"), unit)
			if n(now, "n_restarts") <= n(baseline, "n_restarts") || (same(now["main_pid"], baseline["main_pid"]) && now["process_start"] == baseline["process_start"]) {
				fail("host manager systemd restart count/process identity did not advance")
			}
		} else if !same(now["main_pid"], old["main_pid"]) || now["process_start"] != old["process_start"] || !same(now["n_restarts"], old["n_restarts"]) {
			fail("%s process identity/restart counter changed outside its target scenario", unit)
		}
	}
	return
}

active-validator.text:
func (r *Runner) ValidateActiveObservation(role, phase, observed string) (err error) {
	defer recoverError(&err)
	activeWrite := role == "host_status" && phase == "after_write" && r.State["pressure_started_at"] != nil && r.State["pressure_completed"] != true
	if (phase == "during" && slices.Contains([]string{"service_state", "host_status", "qualify", "database_progress"}, role)) || activeWrite {
		obs := timestamp(observed, "pressure observation")
		if r.State["pressure_started_at"] == nil {
			fail("%s observation did not complete during active pressure", role)
		}
		start := reportTime(r.State, "pressure_started_at")
		if obs.Before(start) || !obs.Before(start.Add(time.Duration(n(r.pressure(), "duration_seconds"))*time.Second)) {
			fail("%s observation did not complete during active pressure", role)
		}
	}
	return
}

validate-pressure.text:
func (r *Runner) ValidatePressure(role string, evidence, response, request Object) (err error) {
	defer recoverError(&err)
	r.validatePressure(role, evidence, response, request)
	return
}
func (r *Runner) validatePressure(role string, evidence, response, request Object) {
	initial := role == "pressure_start"
	if initial {
		if evidence["worker_harness_sha256"] != r.State["harness_sha256"] {
			fail("pressure start did not execute pinned stress worker binary")
		}
		r.State["handle"] = text(evidence["handle"], "pressure handle")
	} else if evidence["handle"] != r.State["handle"] {
		fail("pressure status not bound to active workload handle")
	}
	observed, expected := sub(evidence, "pressure_cgroup"), sub(r.pressure(), "workload_cgroup")
	for _, k := range []string{"cpu_max", "io_device", "memory_max_bytes", "io_weight"} {
		if !same(observed[k], expected[k]) {
			fail("pressure cgroup effective %s differs from pinned workload role", k)
		}
	}
	if n(observed, "memory_min_bytes") != 0 || n(observed, "memory_low_bytes") != 0 {
		fail("pressure cgroup must keep memory.min and memory.low at zero")
	}
	backing, e := ValidateBlockBackingEvidence(observed["io_backing"], str(expected, "io_device"))
	if e != nil {
		panic(e)
	}
	if old := r.State["pressure_backing"]; old != nil && !same(old, backing) {
		fail("pressure scratch block backing changed during run")
	}
	r.State["pressure_backing"] = backing
	path := text(observed["path"], "pressure scope cgroup path")
	parent := str(expected, "parent_path")
	native, db := str(r.State, "native_runner_path"), str(r.State, "database_cgroup_path")
	if !safePath(path) || filepath.Dir(path) != parent || path == native || (native != "" && inside(path, native)) || path == db || (db != "" && inside(db, path)) {
		fail("pressure systemd scope outside pinned slice or overlaps native role tree")
	}
	if old := r.State["pressure_path"]; old != nil && old != path {
		fail("pressure cgroup path changed during run")
	}
	r.State["pressure_path"] = path
	scope := sub(observed, "systemd_scope")
	if !exact(scope, "unit", "slice", "control_group", "parent_control_group", "active_state", "cgroup_present", "systemctl_show_raw") {
		fail("pressure scope evidence differs from exact transient-unit schema")
	}
	runtime := sub(sub(r.Manifest, "transport"), "runtime")
	if str(scope, "unit") != "terrascale-d15-"+str(r.State, "run_id")+".scope" || scope["slice"] != runtime["workload_slice"] || str(scope, "parent_control_group") != strings.TrimPrefix(parent, CgroupRoot) || str(scope, "control_group") != strings.TrimPrefix(path, CgroupRoot) {
		fail("pressure systemd unit placement differs from pinned workload slice")
	}
	completed := request["expect_pressure_completed"] == true
	if (!completed && (str(scope, "active_state") != "active" || scope["cgroup_present"] != true)) || (completed && (!slices.Contains([]string{"inactive", "failed"}, str(scope, "active_state")) || scope["cgroup_present"] != false)) {
		fail("pressure systemd scope lifecycle does not match phase")
	}
	props := parseProperties(text(scope["systemctl_show_raw"], "scope systemctl raw"), "scope")
	for k, want := range map[string]string{"ActiveState": str(scope, "active_state"), "ControlGroup": str(scope, "control_group"), "Slice": str(scope, "slice"), "MemoryMax": strconv.FormatInt(n(expected, "memory_max_bytes"), 10), "MemoryMin": "0", "MemoryLow": "0", "IOWeight": strconv.FormatInt(n(expected, "io_weight"), 10)} {
		if str(props, k) != want {
			fail("systemd scope properties differ from pinned limits or placement")
		}
	}
	f := strings.Fields(str(expected, "cpu_max"))
	quota := integerText(f[0], "CPU quota") * 1000000 / integerText(f[1], "CPU period")
	if str(props, "CPUQuotaPerSecUSec") != strconv.FormatInt(quota, 10) {
		fail("systemd scope CPU quota differs from pinned cpu.max")
	}
	raw := text(observed["worker_state_record"], "pressure worker state record")
	state := obj(rawJSON(raw, "pressure worker state", str(observed, "worker_state_sha256"), 16384), "worker state")
	if str(state, "schema") != "terrascale.d15.pressure-worker-state/v2" || state["run_id"] != r.State["run_id"] || !exact(state, "schema", "run_id", "status", "started_at_utc", "started_monotonic_ns", "observed_at_utc", "elapsed_monotonic_ns", "worker_pids", "worker_roles", "active_worker_pids", "finished_at_utc", "finished_monotonic_ns") {
		fail("pressure worker state not bound to run/version or contains obsolete fields")
	}
	stateObserved, responseObserved := timestamp(state["observed_at_utc"], "worker state observation"), timestamp(response["observed_at_utc"], "pressure response observation")
	if stateObserved.After(responseObserved) {
		fail("pressure worker state future-dated")
	}
	started := timestamp(state["started_at_utc"], "worker state start")
	if initial {
		if str(state, "status") != "RUNNING" {
			fail("pressure worker did not report RUNNING at start")
		}
		r.State["pressure_started_at"], r.State["pressure_started_monotonic"] = started, time.Now()
	} else if !reportTime(r.State, "pressure_started_at").Equal(started) {
		fail("pressure worker start time changed after startup")
	}
	processes, ok := observed["processes"].([]any)
	if !ok {
		fail("pressure cgroup lacks actual process inventory")
	}
	pids := intList(observed["process_pids"], "pressure process pids")
	workers := intList(observed["worker_process_pids"], "pressure worker pids")
	rawProcs := str(observed, "cgroup_procs_raw")
	parsed := []int64{}
	for line := range strings.SplitSeq(strings.TrimSpace(rawProcs), "\n") {
		if line != "" {
			parsed = append(parsed, integerText(line, "cgroup.procs"))
		}
	}
	slices.Sort(parsed)
	if !same(parsed, pids) {
		fail("pressure raw cgroup.procs differs from PID list")
	}
	current := Object{}
	counts := map[string]int{}
	workerRoles := []any{}
	listedWorkers := []int64{}
	for _, v := range processes {
		row := obj(v, "pressure process")
		if !exact(row, "pid", "process_start_time", "role", "process_stat_raw", "process_cgroup_raw") {
			fail("pressure process inventory lacks exact raw /proc identity")
		}
		pid := num(row["pid"], "pressure process PID", 2)
		start, roleName := str(row, "process_start_time"), str(row, "role")
		if !slices.Contains([]string{"pressure_runner", "cpu_worker", "memory_worker", "io_worker"}, roleName) {
			fail("pressure process role not load worker")
		}
		actual, actualStart := procStatIdentity(str(row, "process_stat_raw"))
		group := procCgroupPath(str(row, "process_cgroup_raw"))
		if actual != pid || actualStart != start || filepath.Join(CgroupRoot, group) != path {
			fail("pressure worker raw identity differs from cgroup inventory")
		}
		key := strconv.FormatInt(pid, 10)
		if _, ok := current[key]; ok {
			fail("pressure process inventory repeats PID")
		}
		current[key] = []any{start, roleName}
		counts[roleName]++
		if roleName != "pressure_runner" {
			listedWorkers = append(listedWorkers, pid)
			workerRoles = append(workerRoles, Object{"pid": pid, "role": roleName})
		}
		if snapshot, ok := r.State["host_snapshot"].(map[string]any); ok && pid == n(sub(sub(sub(snapshot, "members"), "source"), "managed_identity"), "pid") {
			fail("pressure cgroup includes TerraBase or management process")
		}
		if service, ok := r.stateObject("service_snapshot")[HostUnit].(map[string]any); ok && pid == n(service, "main_pid") {
			fail("pressure cgroup includes TerraBase or management process")
		}
	}
	currentPids := []int64{}
	for k := range current {
		currentPids = append(currentPids, integerText(k, "PID"))
	}
	slices.Sort(currentPids)
	slices.Sort(listedWorkers)
	slices.SortFunc(workerRoles, func(a, b any) int {
		aa, bb := n(obj(a, "worker role"), "pid"), n(obj(b, "worker role"), "pid")
		if aa < bb {
			return -1
		}
		if aa > bb {
			return 1
		}
		return 0
	})
	if !same(pids, currentPids) || !same(workers, listedWorkers) || Hash(Canonical(processes)) != str(observed, "process_inventory_sha256") {
		fail("pressure process inventory hash or IDs differ from raw records")
	}
	if initial {
		if counts["pressure_runner"] != 1 || int64(counts["cpu_worker"]) != n(r.pressure(), "cpu_workers") || counts["memory_worker"] != 1 || int64(counts["io_worker"]) != n(r.pressure(), "io_workers") {
			fail("pressure startup inventory differs from configured load workers")
		}
		r.State["pressure_processes"] = current
		r.State["pressure_worker_roles"] = workerRoles
		if !same(state["worker_roles"], workerRoles) {
			fail("pressure worker roles differ from startup inventory")
		}
	} else if completed {
		if len(pids) != 0 || len(processes) != 0 || rawProcs != "" || len(workers) != 0 {
			fail("completed pressure left process in cgroup")
		}
	} else {
		if !same(current, r.State["pressure_processes"]) {
			fail("pressure worker disappeared or changed identity before full duration")
		}
		if !same(state["worker_roles"], r.expectedWorkerRoles()) {
			fail("pressure worker state roles changed during duration")
		}
	}
	if completed {
		elapsed, startNS, finishNS := num(state["elapsed_monotonic_ns"], "worker elapsed", 0), num(state["started_monotonic_ns"], "worker start", 0), num(state["finished_monotonic_ns"], "worker finish", 0)
		finish := timestamp(state["finished_at_utc"], "worker finish time")
		if str(state, "status") != "COMPLETED" || !same(state["worker_pids"], []any{}) || !same(state["active_worker_pids"], []any{}) || !same(state["worker_roles"], r.expectedWorkerRoles()) || finishNS <= startNS || elapsed < n(r.pressure(), "duration_seconds")*1000000000 || finish.Before(started.Add(time.Duration(n(r.pressure(), "duration_seconds"))*time.Second)) {
			fail("pressure completion did not prove all workers survived full duration")
		}
		r.State["pressure_completed"] = true
	} else if str(state, "status") != "RUNNING" || !same(state["worker_pids"], listedWorkers) || !same(state["active_worker_pids"], listedWorkers) {
		fail("pressure workers not all running through duration")
	}
}

oom-validator.text:
func (r *Runner) ValidateOOM(evidence, request Object, observed string) (err error) {
	defer recoverError(&err)
	r.validateOOM(evidence, request, observed)
	return
}
func (r *Runner) validateOOM(evidence, request Object, observed string) {
	events, ok := evidence["events"].([]any)
	if !ok || len(events) > 4096 {
		fail("OOM evidence must retain bounded array of raw kernel records")
	}
	if str(request, "phase") == "before" {
		if len(events) > 0 {
			fail("pre-pressure OOM watermark must not contain pre-existing events")
		}
		raw := text(evidence["journal_watermark_raw_record"], "OOM watermark record")
		rawJSON(raw, "OOM watermark", str(evidence, "journal_watermark_raw_record_sha256"), 65536)
		parsed, e := ParseJournalRecord(raw, "kernel")
		if e != nil {
			panic(e)
		}
		watermark := Object{"boot_id": parsed["boot_id"], "cursor": parsed["cursor"], "raw_record": raw, "raw_record_sha256": evidence["journal_watermark_raw_record_sha256"]}
		target := r.terrabaseTarget()
		if !same(request["oom_target"], target) {
			fail("pre-mutation OOM target differs from accepted witness")
		}
		intent := sub(evidence, "oom_restore_intent")
		if !exact(intent, "target", "native_runner_cgroup_path", "database_cgroup_path", "cgroup_inode", "prior_memory_max_bytes", "temporary_memory_max_bytes") {
			fail("OOM pre-mutation restore intent unexpected shape")
		}
		native, db, _ := qualifiedRoleCgroups(str(intent, "native_runner_cgroup_path"), str(target, "cgroup"))
		if !same(intent["target"], targetIdentity(target)) || native != str(r.State, "native_runner_path") || db != str(r.State, "database_cgroup_path") || str(intent, "database_cgroup_path") != db || n(intent, "cgroup_inode") <= 0 || !same(intent["prior_memory_max_bytes"], r.qualification()["database_memory_max_bytes"]) || !same(intent["temporary_memory_max_bytes"], sub(r.pressure(), "oom_fault")["target_memory_max_bytes"]) {
			fail("OOM pre-mutation restore intent differs from exact signed target/cap")
		}
		if e := writeJSON(filepath.Join(r.EvidenceDir, "oom-restore-intent.json"), intent, true); e != nil {
			fail("could not durably persist native OOM restore obligation")
		}
		dir, e := os.Open(r.EvidenceDir)
		if e != nil {
			fail("cannot open restore obligation directory")
		}
		e = dir.Sync()
		dir.Close()
		if e != nil {
			fail("cannot durably sync native OOM restore obligation")
		}
		r.State["oom_watermark"], r.State["oom_restore_intent"], r.State["oom_target"] = watermark, intent, target
		return
	}
	watermark := sub(r.State, "oom_watermark")
	if !same(watermark, request["journal_watermark"]) {
		fail("OOM evidence does not retain pre-pressure kernel cursor/target")
	}
	start := reportTime(r.State, "pressure_started_at")
	target := r.terrabaseTarget()
	if !same(request["oom_target"], target) {
		fail("OOM fault target differs from latest accepted native witness")
	}
	fault := str(request, "phase") == "during" && request["wait_for_event"] == true
	if fault {
		intent := sub(r.State, "oom_restore_intent")
		if !same(request["oom_restore_intent"], intent) {
			fail("OOM mutation missing durable pre-mutation restore obligation")
		}
		sent, report := timestamp(request["sent_at_utc"], "OOM fault sent"), timestamp(request["target_report_observed_at_utc"], "OOM target report")
		age := sent.Sub(report)
		if age < 0 || age > time.Duration(n(sub(r.Manifest, "adapter_contract"), "target_witness_max_age_ms"))*time.Millisecond {
			fail("OOM fault accepted report/process witness stale")
		}
		receipt := sub(evidence, "memory_limit_receipt")
		if !exact(receipt, "target", "prior_memory_max_bytes", "temporary_memory_max_bytes", "observed_memory_current_bytes", "target_cgroup_members_before", "target_child_cgroups_before", "target_cgroup_inode_before", "restored_memory_max_bytes", "restore_method", "restore_verified") {
			fail("OOM memory receipt differs from bounded native-role fault schema")
		}
		cap := n(sub(r.pressure(), "oom_fault"), "target_memory_max_bytes")
		if !same(receipt["target"], targetIdentity(target)) || !same(receipt["prior_memory_max_bytes"], r.qualification()["database_memory_max_bytes"]) || n(receipt, "temporary_memory_max_bytes") != cap || n(receipt, "observed_memory_current_bytes") <= cap || !same(receipt["target_cgroup_members_before"], []any{target["pid"]}) || !same(receipt["target_child_cgroups_before"], []any{}) || !same(receipt["target_cgroup_inode_before"], intent["cgroup_inode"]) || !same(receipt["restored_memory_max_bytes"], r.qualification()["database_memory_max_bytes"]) || !slices.Contains([]string{"same_cgroup_fd", "native_role_recreated"}, str(receipt, "restore_method")) || receipt["restore_verified"] != true {
			fail("OOM memory cap was not safely lowered and restored on the exact native role")
		}
		r.State["oom_restore_receipt"] = receipt
	}
	threshold := start.Add(time.Duration(n(r.pressure(), "scenario_event_after_seconds")) * time.Second)
	collected := timestamp(observed, "OOM evidence observation")
	window := time.Duration(n(sub(r.Manifest, "adapter_contract"), "oom_event_window_seconds")) * time.Second
	for _, v := range events {
		row := obj(v, "OOM event")
		raw := text(row["raw_record"], "OOM raw event")
		rawJSON(raw, "OOM event", str(row, "raw_record_sha256"), 65536)
		parsed, e := ParseKernelOOMRecord(raw)
		if e != nil {
			panic(e)
		}
		when := timestamp(parsed["event_at_utc"], "OOM event timestamp")
		if str(row, "source") == "kernel" && parsed["boot_id"] == watermark["boot_id"] && parsed["journal_cursor"] != watermark["cursor"] && same(parsed["victim_pid"], target["pid"]) && str(parsed, "cgroup_path") == cgroupFilePath(str(target, "cgroup")) && !when.Before(threshold) && !when.After(collected) && when.Sub(threshold) <= window {
			r.State["failure_injection_at"], r.State["failure_observed"], r.State["oom_observed"] = when, true, true
			return
		}
	}
	if str(request, "phase") == "after" {
		fail("kernel OOM records do not identify exact pre-pressure TerraBase process/cgroup")
	}
}

